import { test, expect } from '@playwright/test';

test('本地合成頁 Run test 按鈕可見', async ({ page }) => {
  await page.setContent(`
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <title>Whippet local test</title>
      </head>
      <body>
        <h1>Whippet ready</h1>
        <button>Run test</button>
      </body>
    </html>
  `);

  await expect(page.locator('h1')).toHaveText('Whippet ready');
  await expect(page.getByRole('button', { name: 'Run test' })).toBeVisible();
});
